using System;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;
public static class ResizeDecorPrefabs { public static string Run(){
if(EditorApplication.isCompiling||EditorApplication.isPlaying)throw new Exception("Editor must be idle.");
var scenes=Enumerable.Range(0,UnityEngine.SceneManagement.SceneManager.sceneCount).Select(i=>UnityEngine.SceneManagement.SceneManager.GetSceneAt(i)).Select(s=>s.path+":"+s.isDirty).ToArray();
var paths=AssetDatabase.FindAssets("t:Prefab",new[]{"Assets/Prefabs/Foreground/Grass","Assets/Prefabs/Environment/Signposts"}).Select(AssetDatabase.GUIDToAssetPath).OrderBy(p=>p).ToArray();
if(paths.Length!=8)throw new Exception("Expected 8 prefabs: "+paths.Length);
var report=new List<string>();
foreach(var path in paths){var go=PrefabUtility.LoadPrefabContents(path);try{go.transform.localScale=new Vector3(4,4,1);PrefabUtility.SaveAsPrefabAsset(go,path);}finally{PrefabUtility.UnloadPrefabContents(go);}
var saved=AssetDatabase.LoadAssetAtPath<GameObject>(path);var sr=saved.GetComponent<SpriteRenderer>();var imp=(TextureImporter)AssetImporter.GetAtPath(AssetDatabase.GetAssetPath(sr.sprite));
if(saved.transform.localScale!=new Vector3(4,4,1)||imp.filterMode!=FilterMode.Point)throw new Exception("Validation failed "+path);
report.Add(saved.name+" "+sr.bounds.size.ToString("F3"));}
AssetDatabase.SaveAssets();
var after=Enumerable.Range(0,UnityEngine.SceneManagement.SceneManager.sceneCount).Select(i=>UnityEngine.SceneManagement.SceneManager.GetSceneAt(i)).Select(s=>s.path+":"+s.isDirty).ToArray();if(!scenes.SequenceEqual(after))throw new Exception("Scene dirty state changed");
return string.Join("\n",report)+"\nScene dirty state preserved. CompilationFailed="+EditorUtility.scriptCompilationFailed;
}}
